# Route panel like Organic Maps: time • km, climb / descent / max / min height, profile with a finger, waypoints (add, drag, remove),
# big «Начать»; «Линейка» (straight lines); «+», «−», «моё место» buttons on the map.
import asyncio, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from harness import serve, Mocks, open_app
from playwright.async_api import async_playwright
RES = []; SHOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '.cache')
def check(n, ok, info=''): RES.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + n + (f' — {info}' if info != '' else ''))
async def main():
    url = serve(8771)
    async with async_playwright() as p:
        for lang, vp in (('ru', (390, 844)), ('he', (375, 667)), ('en', (375, 667))):
            b, ctx, pg, log = await open_app(p, url + f'?lang={lang}', Mocks(), viewport=vp)
            z = await pg.evaluate("['z-in','z-out','z-me'].map(i => { const e = document.getElementById(i), r = e.getBoundingClientRect(); return !e.hidden && !e.classList.contains('ovh') && r.right <= innerWidth && r.width > 30; })")
            check(f'[{lang}] zoom and «my place» buttons on the map', all(z), z)
            z0 = await pg.evaluate("map.getZoom()"); await pg.click('#z-in'); await pg.wait_for_timeout(400); z1 = await pg.evaluate("map.getZoom()"); await pg.click('#z-out'); await pg.wait_for_timeout(400)
            check(f'[{lang}] «+» / «−» zoom', z1 == z0 + 1 and await pg.evaluate("map.getZoom()") == z0, (z0, z1))
            await pg.evaluate("showTab('routes'); routeSeg('plan'); document.getElementById('pl-fromgps').checked = false; Plan.wps = []; addWp([32.09, 34.88], 'Старт'); addWp([32.1, 34.9], 'Финиш')")
            await pg.click('#pl-go'); await pg.wait_for_function("Plan.cand && !document.getElementById('pl-result').hidden", timeout=15000); await pg.wait_for_timeout(500)
            st = await pg.evaluate("({t: document.getElementById('r-time').textContent, d: document.getElementById('r-dist').textContent, a: document.getElementById('r-asc').textContent, de: document.getElementById('r-desc').textContent, mx: document.getElementById('r-emax').textContent, mn: document.getElementById('r-emin').textContent, prof: !document.getElementById('r-prof').hidden, rows: document.querySelectorAll('#r-wps .prw').length, go: document.getElementById('r-nav').textContent})")
            check(f'[{lang}] panel: time • km, climb, descent, max, min, profile, 2 points, «Начать»', st['t'] != '—' and st['d'] != '—' and st['mx'] != '—' and st['mn'] != '—' and st['de'] != '—' and st['prof'] and st['rows'] == 2 and '▶' in st['go'], st)
            await pg.evaluate("document.getElementById('r-prof').scrollIntoView({block: 'center'})"); await pg.wait_for_timeout(200)
            bx = await pg.evaluate("(r => [r.x, r.y, r.width, r.height])(document.getElementById('r-prof').getBoundingClientRect())")
            await pg.mouse.click(bx[0] + bx[2] * .6, bx[1] + bx[3] * .5); await pg.wait_for_timeout(200)
            sc = await pg.evaluate("({t: document.getElementById('r-profx').textContent, dot: !!Plan.dot})")
            check(f'[{lang}] finger on the profile → km and height, point on the map', sc['dot'] and ('км' in sc['t'] or 'km' in sc['t'] or 'ק' in sc['t']), sc)
            await pg.screenshot(path=os.path.join(SHOT, f'plan-panel-{lang}.png'))
            if lang == 'ru':
                await pg.evaluate("document.getElementById('sheet-routes').scrollTop = 1e5"); await pg.wait_for_timeout(200)
                await pg.screenshot(path=os.path.join(SHOT, 'plan-panel-ru-2.png'))
                await pg.click('#r-addstop'); await pg.evaluate("addWp([32.095, 34.885], 'Остановка')"); await pg.wait_for_function("document.querySelectorAll('#r-wps .prw').length === 3 && !document.getElementById('pl-go').disabled", timeout=15000)
                names = await pg.evaluate("Plan.wps.map(w => w.name)")
                check('«Добавить остановку» → before the finish, route rebuilt', names == ['Старт', 'Остановка', 'Финиш'], names)
                await pg.evaluate("document.getElementById('r-wps').scrollIntoView({block: 'center'})"); await pg.wait_for_timeout(200)
                hb = await pg.evaluate("[...document.querySelectorAll('#r-wps .prh')].map(h => (r => [r.x + r.width / 2, r.y + r.height / 2])(h.getBoundingClientRect()))")
                await pg.mouse.move(*hb[2]); await pg.mouse.down(); await pg.mouse.move(hb[0][0], hb[0][1] - 10, steps=8); await pg.mouse.up()
                await pg.wait_for_timeout(300); await pg.wait_for_function("!document.getElementById('pl-go').disabled", timeout=15000)
                names = await pg.evaluate("Plan.wps.map(w => w.name)")
                check('drag ≡ changes the order and rebuilds', names[0] == 'Финиш', names)
                await pg.click('#r-wps [data-rx="1"]'); await pg.wait_for_function("Plan.wps.length === 2 && !document.getElementById('pl-go').disabled", timeout=15000)
                check('✕ removes a stop', await pg.evaluate("Plan.wps.length") == 2)
                await pg.evaluate("document.getElementById('pl-mode').scrollIntoView({block: 'center'})"); await pg.click('#pl-mode [data-m=line]'); await pg.wait_for_timeout(200)
                hid = await pg.evaluate("({bike: document.getElementById('pl-bike').hidden, eng: document.getElementById('pl-engine-box').hidden, on: document.querySelector('#pl-mode [data-m=line]').classList.contains('on')})")
                n0 = len(await pg.evaluate("Mocks_calls = 0; []"))
                await pg.click('#pl-go'); await pg.wait_for_function("Plan.cand && Plan.cand.ruler && !document.getElementById('pl-go').disabled", timeout=15000)
                rl = await pg.evaluate("({n: Plan.cand.coords.length, d: Plan.cand.distance, e: Plan.cand.engine, nav: navMode(Plan.cand), h: Plan.cand.coords[5][2]})")
                check('«Линейка»: straight lines, heights, our navigation, bike options hidden', hid['bike'] and hid['on'] and rl['n'] > 50 and 'Линейка' in rl['e'] and rl['nav'] == 'app' and rl['h'] is not None, {**hid, **rl})
                await pg.click('#pl-mode [data-m=bike]'); check('back to «Велосипед» switches the ruler off', not await pg.evaluate("rulerOn"))
                await pg.evaluate("showTab('profile')"); await pg.click('#s-zoombtns'); await pg.evaluate("showTab('rec')"); await pg.wait_for_timeout(300)
                check('setting off → zoom buttons hidden', await pg.evaluate("document.getElementById('z-in').hidden && lsGet('settings').zoomBtns === false"))
            check(f'[{lang}] no JS errors', not log['errors'], log['errors'][:3])
            await b.close()
    print(f'{sum(RES)}/{len(RES)} passed'); sys.exit(0 if all(RES) else 1)
asyncio.run(main())
